-- Geo: every bid in Geo Bids' Won and Lost columns also goes to Won and Lost on Geo Follow-Up. Bids that already have a follow-up copy have that copy moved to the same column; the rest get a new copy with everything on it (same people, fields, files, comments and history). Nobody is emailed. Safe to run more than once.
with g as (select s.* from wf_spaces s where s.parent_id is null and s.division_id in (select id::text from divisions where lower(name) = 'geo')), f as (select t.* from wf_spaces t join g on t.parent_id = g.id where t.name ilike '%follow%'), m as (select g.id sid, oe ->> 'id' ocol, f.id tid, f.division_id tdiv, te ->> 'id' tcol, te ->> 'name' tname, te ->> 'cat' tcat from g, f, jsonb_array_elements(g.statuses) oe, jsonb_array_elements(f.statuses) te where lower(oe ->> 'name') in ('won', 'lost') and lower(te ->> 'name') = lower(oe ->> 'name')) update wf_bids c set status = m.tcol, done_at = case when m.tcat = 'done' then coalesce(c.done_at, o.done_at, current_date) else c.done_at end, history = coalesce(c.history, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('by', 'Automation', 'at', (extract(epoch from now()) * 1000)::bigint, 'field', 'Status', 'from', coalesce((select e ->> 'name' from jsonb_array_elements((select statuses from wf_spaces where id = c.space_id)) e where e ->> 'id' = c.status limit 1), ''), 'to', m.tname)), updated_at = now() from wf_bids o join m on o.space_id = m.sid and o.status = m.ocol where c.origin_bid_id = o.id and c.space_id = m.tid and c.status is distinct from m.tcol;
with g as (select s.* from wf_spaces s where s.parent_id is null and s.division_id in (select id::text from divisions where lower(name) = 'geo')), f as (select t.* from wf_spaces t join g on t.parent_id = g.id where t.name ilike '%follow%'), m as (select g.id sid, oe ->> 'id' ocol, f.id tid, f.division_id tdiv, te ->> 'id' tcol, te ->> 'name' tname, te ->> 'cat' tcat from g, f, jsonb_array_elements(g.statuses) oe, jsonb_array_elements(f.statuses) te where lower(oe ->> 'name') in ('won', 'lost') and lower(te ->> 'name') = lower(oe ->> 'name')), x as (select f.id, greatest(coalesce((select max(num) from wf_bids where space_id = f.id), 0), f.next - 1) n0, coalesce((select max(rank) from wf_bids where space_id = f.id), 0) r0 from f) insert into wf_bids (space_id, division_id, num, rank, type, title, descr, status, priority, assignee, reporter, labels, due, due_time, created, done_at, fields, attachments, comments, history, source_url, origin_bid_id) select m.tid, m.tdiv, x.n0 + row_number() over (order by o.num), x.r0 + 1000 * row_number() over (order by o.num), o.type, o.title, o.descr, m.tcol, o.priority, o.assignee, o.reporter, o.labels, o.due, o.due_time, o.created, case when m.tcat = 'done' then coalesce(o.done_at, current_date) end, o.fields, o.attachments, o.comments, coalesce(o.history, '[]'::jsonb) || jsonb_build_array(jsonb_build_object('by', 'Automation', 'at', (extract(epoch from now()) * 1000)::bigint, 'field', 'created')), o.source_url, o.id from wf_bids o join m on o.space_id = m.sid and o.status = m.ocol join x on x.id = m.tid where o.type <> 'Subtask' and not exists (select 1 from wf_bids c where c.origin_bid_id = o.id and c.space_id = m.tid) on conflict (origin_bid_id, space_id) where origin_bid_id is not null do nothing;
update wf_spaces t set next = greatest(t.next, (select coalesce(max(num), 0) + 1 from wf_bids where space_id = t.id)) where t.parent_id in (select s.id from wf_spaces s where s.parent_id is null and s.division_id in (select id::text from divisions where lower(name) = 'geo')) and t.name ilike '%follow%';
insert into wf_notify (bid_id, through) select b.id::text, (extract(epoch from now()) * 1000)::bigint + 1000 from wf_bids b join wf_spaces t on t.id = b.space_id where t.parent_id in (select s.id from wf_spaces s where s.parent_id is null and s.division_id in (select id::text from divisions where lower(name) = 'geo')) and t.name ilike '%follow%' and b.updated_at > now() - interval '5 minutes' on conflict (bid_id) do update set through = greatest(wf_notify.through, excluded.through);
select t.name as space, e ->> 'name' as column_name, count(*) as bids from wf_bids b join wf_spaces t on t.id = b.space_id cross join jsonb_array_elements(t.statuses) e where e ->> 'id' = b.status and lower(e ->> 'name') in ('won', 'lost') and t.division_id in (select id::text from divisions where lower(name) = 'geo') group by 1, 2 order by 1, 2;
